int nl_dump(struct sock *sk)
{
    struct sk_buff *skb = NULL;
    int err = 0;

    mutex_lock(&sk->sk_mutex);
    if (sk->sk_data_input && sk->sk_data_input(sk)) {
        err = -EBUSY;
        goto unlock_mutex;
    }

    skb = alloc_skb(NLMSG_SPACE(4096), GFP_KERNEL);
    if (!skb) {
        err = -ENOMEM;
        goto unlock_mutex;
    }

    err = sk->sk_user_data ? ((struct nl_dump_cb *)sk->sk_user_data)->dump(skb) : -EINVAL;
    if (err < 0)
        goto free_skb;

    if (((struct nl_dump_cb *)sk->sk_user_data)->filter) {
        err = ((struct nl_dump_cb *)sk->sk_user_data)->filter(skb);
        if (err < 0)
            goto free_skb;
        err = 0;
    }

    if (err == 0)
        netlink_unicast(sk, skb, NETLINK_CB(skb).portid, MSG_DONTWAIT);
    else
        kfree_skb(skb);

free_skb:
    if (sk->sk_user_data)
        ((struct nl_dump_cb *)sk->sk_user_data)->done();

unlock_mutex:
    mutex_unlock(&sk->sk_mutex);
    return err;
}

int netlink_dump(struct sock *sk)
{
    struct sk_buff *skb;
    int err = 0;

    mutex_lock(&sk->netlink_mutex);
    if (sk->protinfo.af_netlink.cb_running) {
        mutex_unlock(&sk->netlink_mutex);
        return -EBUSY;
    }

    skb = alloc_skb(4096, GFP_KERNEL);
    if (!skb) {
        err = -ENOMEM;
        goto out;
    }

    sk->protinfo.af_netlink.cb_running = 1;
    err = sk->protinfo.af_netlink.dump(sk, skb);
    if (err < 0)
        goto out_free_skb;

    if (sk->protinfo.af_netlink.cb_filter)
        skb_trim(skb, sk->protinfo.af_netlink.cb_filter(skb));
    else
        skb_trim(skb, skb->len);

    if (skb->len)
        netlink_unicast(sk, skb, NETLINK_CB(skb).portid, MSG_DONTWAIT);
    else
        kfree_skb(skb);

    sk->protinfo.af_netlink.cb_running = 0;
out:
    mutex_unlock(&sk->netlink_mutex);
    return err;

out_free_skb:
    kfree_skb(skb);
    sk->protinfo.af_netlink.cb_running = 0;
    goto out;
}

int netlink_dump(struct sock *sk)
{
    struct sk_buff *skb = NULL;
    int ret = 0;

    mutex_lock(&sk->sk_mutex);
    if (sk->sk_protinfo && ((struct netlink_sock *)sk->sk_protinfo)->dump) {
        if (sk_rcvqueues_full(sk, 1))
            goto out;

        skb = alloc_skb(NETLINK_RECVmsg_SPACE, GFP_KERNEL);
        if (!skb) {
            ret = -ENOMEM;
            goto out;
        }

        ret = ((struct netlink_sock *)sk->sk_protinfo)->dump(sk, skb);
        if (ret < 0)
            goto out;

        if (!skb->sk)
            skb_set_owner_r(skb, sk);

        if (sk_filter(sk, skb))
            kfree_skb(skb);
        else
            sock_wfree(skb);
    }
out:
    mutex_unlock(&sk->sk_mutex);
    return ret;
}
